def export_device_telemetry(request, device_id):
    device = get_object_or_404(Device, id=device_id, fleet__organization=request.user.organization)
    data = list(device.telemetry_readings.order_by('-timestamp').values_list(
        'timestamp', 'latitude', 'longitude', 'speed', named=True
    )[:500])
    return JsonResponse({'device_id': device.id, 'breadcrumbs': [d._asdict() for d in data]})
